import { AnimationController } from './game.js';
export class SpriteSheetLoader {
 constructor(){this.cache=new Map();}
 async load(){this.meta=await fetch('assets/sprites/atlas.json').then(r=>{if(!r.ok)throw Error('Métadonnées absentes');return r.json();});await Promise.all(['w','b'].flatMap(c=>['p','n','b','r','q','k'].map(async p=>{const i=new Image();i.src=`assets/sprites/${c}${p}.png`;await i.decode();this.cache.set(c+p,i);})));return this;}
}
export class SpriteRenderer {
 constructor(loader){this.loader=loader;}
 draw(ctx,p,x,y,size,state='idle',elapsed=0,opacity=1){const m=this.loader.meta,a=m.animations[state],frame=a.loop?Math.floor(elapsed/a.frameDuration)%a.frames:Math.min(7,Math.floor(elapsed/a.frameDuration));ctx.save();ctx.globalAlpha=opacity;ctx.drawImage(this.loader.cache.get(p.color+p.type),frame*m.frameWidth,a.row*m.frameHeight,m.frameWidth,m.frameHeight,x-size*.5,y-size*.9,size,size*1.25);ctx.restore();}
}
export class ParticleSystem {
 constructor(){this.items=[];}
 emit(x,y,color,amount=22){for(let i=0;i<amount;i++){const a=Math.random()*Math.PI*2,s=35+Math.random()*100;this.items.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:350+Math.random()*400,max:750,color});}}
 update(dt){this.items=this.items.filter(p=>p.life>0);for(const p of this.items){p.x+=p.vx*dt/1000;p.y+=p.vy*dt/1000;p.vy+=70*dt/1000;p.life-=dt;}}
 draw(ctx){for(const p of this.items){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,2.5,2.5);}ctx.globalAlpha=1;}
}
export class SoundManager {
 constructor(){this.enabled=false;this.volume=.35;}
 unlock(){if(!this.context)this.context=new (window.AudioContext||window.webkitAudioContext)();this.context.resume();}
 play(kind='move'){if(!this.enabled)return;this.unlock();const ctx=this.context,o=ctx.createOscillator(),g=ctx.createGain(),now=ctx.currentTime;o.type=kind==='impact'?'triangle':'sine';o.frequency.setValueAtTime(kind==='impact'?180:kind==='check'?660:380,now);o.frequency.exponentialRampToValueAtTime(kind==='impact'?40:240,now+.18);g.gain.setValueAtTime(this.volume*.18,now);g.gain.exponentialRampToValueAtTime(.001,now+.25);o.connect(g);g.connect(ctx.destination);o.start();o.stop(now+.26);}
}
export class CombatAnimator {
 constructor(loader,transaction,onImpact){this.transaction=transaction;this.phase='MOVING';this.elapsed=0;this.movingTime=650;this.targetTime=0;this.hit=false;this.done=false;this.meta=loader.meta;this.attack=new AnimationController(loader.meta,'attack',()=>{this.hit=true;onImpact();});}
 update(dt){this.elapsed+=dt;if(this.phase==='MOVING'&&this.elapsed>=this.movingTime){this.elapsed=0;this.phase=this.transaction.move.captured?'ATTACKING':'RECOVERING';}else if(this.phase==='ATTACKING'){this.attack.update(dt);if(this.hit)this.targetTime+=dt;if(this.attack.done){this.phase='RECOVERING';this.elapsed=0;}}else if(this.phase==='RECOVERING'){if(this.hit)this.targetTime+=dt;if(this.elapsed> (this.hit?760:120))this.done=true;}}
 get progress(){return Math.min(1,this.elapsed/this.movingTime);}
}
export class BoardRenderer {
 constructor(canvas,session,loader,settings,sound){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.session=session;this.loader=loader;this.sprites=new SpriteRenderer(loader);this.settings=settings;this.sound=sound;this.particles=new ParticleSystem();this.flipped=false;this.lastMove=null;this.animator=null;this.shake=0;this.time=0;this.keyboard=null;this.mateTime=0;this.onFinish=()=>{};this.resize=()=>{const rect=canvas.getBoundingClientRect();const dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(rect.width*dpr);canvas.height=canvas.width;};this.observer=new ResizeObserver(this.resize);this.observer.observe(canvas);this.resize();}
 squarePoint(square){let col=square.charCodeAt(0)-97,row=8-Number(square[1]);if(this.flipped){col=7-col;row=7-row;}return {x:50+col*100+50,y:50+row*100+50};}
 at(x,y){let c=Math.floor((x-50)/100),r=Math.floor((y-50)/100);if(c<0||c>7||r<0||r>7)return null;if(this.flipped){c=7-c;r=7-r;}return String.fromCharCode(97+c)+(8-r);}
 start(tx){this.lastMove=tx.move;this.particles.items=[];const target=this.squarePoint(tx.move.to);this.animator=new CombatAnimator(this.loader,tx,()=>{const p=this.squarePoint(tx.move.to);this.particles.emit(p.x,p.y-25,['b','q'].includes(tx.move.piece)?'#98dfcb':'#f1cf8a',Math.round(28*this.settings.particles));this.sound.play('impact');if(!this.settings.reduced)this.shake=tx.move.piece==='r'?9:4;});if(tx.move.promotion)this.particles.emit(target.x,target.y,'#f7e4a2',35*this.settings.particles);if(this.settings.mode==='off')this.skip();}
 skip(){if(!this.animator&&!this.session.busy)return;this.animator=null;this.session.finish();this.particles.items=[];this.onFinish();}
 reset(){this.animator=null;this.lastMove=null;this.particles.items=[];this.mateTime=0;}
 update(dt){this.time+=dt;this.shake=Math.max(0,this.shake-dt*.035);this.particles.update(dt);if(this.animator){this.animator.update(dt*(this.settings.mode==='fast'?2.5:1)*this.settings.speed);if(this.animator.done)this.skip();}}
 draw(){const ctx=this.ctx,n=this.canvas.width;ctx.setTransform(n/900,0,0,n/900,0,0);ctx.clearRect(0,0,900,900);ctx.fillStyle='#222c20';ctx.fillRect(0,0,900,900);ctx.save();if(this.shake&&!this.settings.reduced)ctx.translate(Math.sin(this.time)*this.shake,Math.cos(this.time)*this.shake);for(let r=0;r<8;r++)for(let c=0;c<8;c++){const x=50+c*100,y=50+r*100;ctx.fillStyle=(r+c)%2?'#45523e':'#9ca786';ctx.fillRect(x,y,100,100);const grd=ctx.createLinearGradient(x,y,x+100,y+100);grd.addColorStop(0,'#ffffff09');grd.addColorStop(1,'#0000000c');ctx.fillStyle=grd;ctx.fillRect(x,y,100,100);ctx.strokeStyle='#17271b15';ctx.strokeRect(x+.5,y+.5,99,99);for(let j=0;j<4;j++){ctx.strokeStyle=(r+c)%2?'#b0bc9a06':'#263b2308';ctx.beginPath();ctx.moveTo(x+3,y+15+j*24);ctx.lineTo(x+98,y+11+j*24);ctx.stroke();}}
 ctx.fillStyle='#9fa98e';ctx.font='15px Georgia';ctx.textAlign='center';for(let i=0;i<8;i++){ctx.fillText(String.fromCharCode(97+(this.flipped?7-i:i)),100+i*100,879);ctx.fillText(String.fromCharCode(97+(this.flipped?7-i:i)),100+i*100,32);ctx.fillText(String(this.flipped?i+1:8-i),25,106+i*100);ctx.fillText(String(this.flipped?i+1:8-i),875,106+i*100);}
 const highlight=(sq,color,outline=false)=>{const p=this.squarePoint(sq);ctx.fillStyle=color;ctx.fillRect(p.x-50,p.y-50,100,100);if(outline){ctx.strokeStyle='#edd58d';ctx.lineWidth=2;ctx.strokeRect(p.x-47,p.y-47,94,94);}};
 if(this.lastMove){highlight(this.lastMove.from,'#e2cf6426');highlight(this.lastMove.to,'#e2cf6444');}if(this.session.selected)highlight(this.session.selected,'#e0c46b66',true);if(this.keyboard)highlight(this.keyboard,'#dfc98522',true);
 if(this.session.chess.isCheck()){const king=this.session.chess.board().flat().find(p=>p&&p.type==='k'&&p.color===this.session.chess.turn());if(king)highlight(king.square,`rgba(185,65,64,${.28+Math.sin(this.time/250)*.1})`,true);}
 if(this.session.selected&&!this.session.busy){for(const m of this.session.chess.moves({square:this.session.selected,verbose:true})){const p=this.squarePoint(m.to);ctx.fillStyle='#203c26aa';ctx.strokeStyle='#f3df9e99';ctx.lineWidth=3;ctx.beginPath();ctx.arc(p.x,p.y,m.captured?42:11,0,Math.PI*2);m.captured?ctx.stroke():ctx.fill();}}
 const a=this.animator,tx=a?.transaction;const pieces=tx?tx.before:this.session.chess.board().flat().filter(Boolean);let visuals=[];for(const p of pieces){if(tx&&(p.square===tx.move.from||p.square===tx.captureSquare&&tx.move.captured||tx.move.isKingsideCastle()&&p.square===(tx.move.color==='w'?'h1':'h8')||tx.move.isQueensideCastle()&&p.square===(tx.move.color==='w'?'a1':'a8')))continue;visuals.push({...p,...this.squarePoint(p.square),state:'idle',elapsed:this.time});}
 if(a){const from=this.squarePoint(tx.move.from),to=this.squarePoint(tx.move.to);const progress=a.phase==='MOVING'?a.progress:1;const capture=!!tx.move.captured;const approach=capture?Math.max(.2,1-45/Math.hypot(to.x-from.x,to.y-from.y)):1;const recovery=a.phase==='RECOVERING'?Math.min(1,a.elapsed/500):0;const smooth=a.phase==='MOVING'?progress*progress*(3-2*progress)*approach:approach+(1-approach)*recovery*recovery*(3-2*recovery);const x=from.x+(to.x-from.x)*smooth,y=from.y+(to.y-from.y)*smooth-(tx.move.piece==='n'?Math.sin(progress*Math.PI)*48:0);visuals.push({color:tx.move.color,type:tx.move.promotion&&a.phase==='RECOVERING'?tx.move.promotion:tx.move.piece,x,y,state:a.phase==='MOVING'?'walk':a.phase==='ATTACKING'?'attack':capture?'victory':'idle',elapsed:a.phase==='ATTACKING'?a.attack.elapsed:a.elapsed,attacker:true});
 if(capture){const victim=tx.before.find(p=>p.square===tx.captureSquare);if(victim&&a.targetTime<1000)visuals.push({...victim,...this.squarePoint(tx.captureSquare),state:!a.hit?'idle':a.targetTime<240?'hit':'death',elapsed:!a.hit?this.time:a.targetTime<240?a.targetTime:a.targetTime-240,opacity:a.targetTime>700?Math.max(0,1-(a.targetTime-700)/300):1});}
 if(tx.move.isKingsideCastle()||tx.move.isQueensideCastle()){const rank=tx.move.from[1],ks=tx.move.isKingsideCastle(),rf=this.squarePoint((ks?'h':'a')+rank),rt=this.squarePoint((ks?'f':'d')+rank);visuals.push({color:tx.move.color,type:'r',x:rf.x+(rt.x-rf.x)*smooth,y:rf.y,state:'walk',elapsed:a.elapsed});}}
 visuals.sort((a,b)=>a.y-b.y||(a.attacker?1:-1));for(const p of visuals){ctx.fillStyle='#0b140a55';ctx.beginPath();ctx.ellipse(p.x,p.y+29,p.type==='n'?34:25,10,0,0,Math.PI*2);ctx.fill();let state=p.state,elapsed=p.elapsed;if(!tx&&this.session.chess.isCheckmate()){if(p.color===this.session.chess.turn()&&p.type==='k'){state='death';elapsed=Math.min(650,this.mateTime);}else if(p.color!==this.session.chess.turn()){state='victory';elapsed=this.time%680;}}this.sprites.draw(ctx,p,p.x,p.y+27,p.type==='n'?100:94,state,this.settings.mode==='off'?0:elapsed,p.opacity??1);}
 if(this.session.chess.isCheckmate())this.mateTime+=16;this.particles.draw(ctx);ctx.restore();}
}
